function jsonScript(data) {
  const json = JSON.stringify(data).replace(/</g, '\\u003c');
  cspHashes.add(`'sha256-${createHash('sha256').update(json).digest('base64')}'`);
  return `<script type="application/ld+json">${json}</script>`;
}

function collectInlineScriptHashes(html) {
  for (const match of html.matchAll(/<script(?![^>]*\bsrc=)[^>]*>([\s\S]*?)<\/script>/gi)) {
    cspHashes.add(`'sha256-${createHash('sha256').update(match[1]).digest('base64')}'`);
  }
}

function shell({ title, description, canonical, current, body, structured, type = 'website', locale = 'pt', alternatesKey = current }) {
  const url = `${origin}${canonical}`;
  const meta = localeMeta[locale];
  const alternates = alternatesKey
    ? Object.keys(localeMeta)
      .filter(code => localizedRoutes[code]?.[alternatesKey])
      .map(code => `<link rel="alternate" hreflang="${localeMeta[code].lang}" href="${origin}${routeFor(code, alternatesKey)}">`)
      .concat(`<link rel="alternate" hreflang="x-default" href="${origin}${routeFor('pt', alternatesKey)}">`)
      .join('')
    : '';
  renderedCurrent = current || 'home';
  return `<!doctype html><html lang="${meta.lang}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><title>${title}</title><meta name="description" content="${description}"><meta name="author" content="Pascoal Eti"><meta name="application-name" content="Rumman"><meta name="robots" content="index, follow, max-image-preview:large"><link rel="canonical" href="${url}">${alternates}<meta property="og:locale" content="${meta.og}"><meta property="og:type" content="${type}"><meta property="og:site_name" content="Rumman"><meta property="og:title" content="${title}"><meta property="og:description" content="${description}"><meta property="og:url" content="${url}"><meta property="og:image" content="${origin}/assets/rumman-social.png"><meta property="og:image:width" content="1200"><meta property="og:image:height" content="630"><meta property="og:image:alt" content="Rumman, ERP inteligente guiado para Android"><meta name="twitter:card" content="summary_large_image"><meta name="twitter:title" content="${title}"><meta name="twitter:description" content="${description}"><meta name="twitter:image" content="${origin}/assets/rumman-social.png"><meta name="twitter:image:alt" content="Rumman, ERP inteligente guiado para Android"><meta name="theme-color" content="#FCF9FD" media="(prefers-color-scheme: light)"><meta name="theme-color" content="#17121F" media="(prefers-color-scheme: dark)"><link rel="icon" href="/favicon.ico" sizes="any"><link rel="manifest" href="/site.webmanifest"><link rel="preload" href="/assets/fonts/sora-latin-variable.woff2" as="font" type="font/woff2" crossorigin><link rel="preload" href="/assets/fonts/inter-latin-variable.woff2" as="font" type="font/woff2" crossorigin><link rel="stylesheet" href="/assets/site.css?v=${assetVersion}"><script src="/assets/theme-init.js?v=${assetVersion}"></script>${jsonScript(structured)}</head><body><a class="skip-link" href="#conteudo">${meta.skip}</a>${header(current, locale)}<main id="conteudo">${body}</main>${footer(locale)}<script src="/assets/site.js?v=${assetVersion}" defer></script></body></html>`.replaceAll('href="/blog"', 'href="/blog/"');
}

function pageHero(eyebrow, title, lead, extra = '') {
  return `<section class="page-hero marketing-hero"><div class="wrap page-hero-inner"><div><p class="eyebrow">${eyebrow}</p><h1>${title}</h1><p class="hero-lead">${lead}</p></div>${extra}</div></section>`;
}

function cta(locale = 'pt') {
  const copy = locale === 'en' ? { eyebrow: 'Rumman · Guided Intelligent ERP', title: 'Clearer management for work with less friction.', lead: 'Organize customers, cash flow, documents and everyday decisions in a guided Android experience.', action: 'Discover features' } : locale === 'es' ? { eyebrow: 'Rumman · ERP Inteligente Guiado', title: 'Gestión clara para trabajar con menos fricción.', lead: 'Organiza clientes, caja, documentos y decisiones diarias en una experiencia Android guiada.', action: 'Conocer funciones' } : locale === 'fr' ? { eyebrow: 'Rumman · ERP Intelligent Guidé', title: 'Une gestion plus claire pour travailler avec moins de friction.', lead: 'Organisez clients, trésorerie, documents et décisions quotidiennes dans une expérience Android guidée.', action: 'Découvrir les fonctions' } : { eyebrow: 'Rumman · ERP Inteligente Guiado', title: 'Gestão clara para trabalhar com menos atrito.', lead: 'Organize clientes, caixa, documentos e decisões do dia a dia em uma experiência Android guiada.', action: 'Falar com o Rumman' };
  const href = locale === 'pt' ? 'mailto:e-mail@rumman.app.br?subject=Quero%20conhecer%20o%20Rumman' : routeFor(locale, 'features');
  return `<section class="final-cta"><div class="wrap final-cta-inner"><div><p class="eyebrow">${copy.eyebrow}</p><h2>${copy.title}</h2><p>${copy.lead}</p></div><a class="button primary" href="${href}">${copy.action}</a></div></section>`;
}

function writeRoute(route, html) {
  const cleanRoute = route.replace(/^\//, '');
  const file = route === '/' || route.endsWith('/')
    ? join(root, cleanRoute, 'index')
    : join(root, cleanRoute);
  mkdirSync(dirname(file), { recursive: true });
  writeFileSync(file, html, 'utf8');
}

