const howBody = `${pageHero('Como funciona', 'Fatos da operação viram decisões claras para hoje.', 'O Rumman não promete uma IA mágica. Ele usa regras locais e determinísticas para orientar o trabalho, preservando a confirmação humana.', illustration('illustration-workflow.svg'))}<section class="section guided-section"><div class="wrap"><ol class="cycle-list">${cycle.map((step, i) => `<li><span class="cycle-number">${String(i + 1).padStart(2, '0')}</span><div><h2>${step[0]}</h2><p>${step[1]}</p></div></li>`).join('')}</ol></div></section><section class="section comparison-section"><div class="wrap comparison-grid"><div class="comparison-intro"><p class="eyebrow">Uma comparação honesta</p><h2>Não é sobre ter mais menus. É sobre reduzir procura e retrabalho.</h2><p>A comparação é conceitual: recursos e preços de outros fornecedores mudam e devem ser conferidos nas fontes oficiais no momento da contratação.</p></div><table class="comparison-table"><thead><tr class="comparison-row comparison-header"><th>Sistema centrado em módulos</th><th>Rumman guiado</th></tr></thead><tbody><tr class="comparison-row"><td>O usuário procura o relatório e interpreta sozinho</td><td>A fila aponta o fato e abre o registro certo</td></tr><tr class="comparison-row"><td>As mesmas informações voltam a ser digitadas</td><td>Orçamento, ordem, estoque e financeiro compartilham contexto</td></tr><tr class="comparison-row"><td>A automação pode esconder o impacto</td><td>Ações sensíveis exigem confirmação explícita</td></tr><tr class="comparison-row"><td>Depende da internet para tarefas básicas</td><td>A operação local continua nas rotinas que não exigem nuvem</td></tr></tbody></table></div></section>${cta()}`;
writeRoute('/como-funciona', shell({ title: 'Como funciona o Rumman | Gestão guiada com confirmação humana', description: 'Veja como o Rumman cruza fatos locais, prioriza pendências e abre o caminho certo sem tirar o controle da pequena empresa.', canonical: '/como-funciona', current: 'how', body: howBody, structured: { ...software, url: `${origin}/como-funciona` } }));

const plansBody = `${pageHero('Planos', 'Referências para o lançamento no Brasil.', 'O Rumman está em testes fechados. Quando a oferta pública for liberada, contratação, teste e cobrança acontecerão somente pelo Google Play.', illustration('illustration-plans.svg'))}<section class="section plans-section"><div class="wrap"><div class="plans-grid"><article class="plan"><p class="plan-label">Referência de lançamento</p><p class="plan-name">Essencial</p><p class="plan-price"><strong>R$ 49,90</strong><span>/mês</span></p><p class="plan-annual">referência anual: R$ 499</p><ul><li>1 empresa</li><li>1 usuário</li><li>Fluxos essenciais do ERP</li><li>Cota mensal de recursos online</li></ul></article><article class="plan plan-featured"><p class="plan-label">Referência de lançamento</p><p class="plan-name">Pro</p><p class="plan-price"><strong>R$ 89,90</strong><span>/mês</span></p><p class="plan-annual">referência anual: R$ 899</p><ul><li>Até 3 usuários</li><li>Sincronização autorizada</li><li>Relatórios avançados</li><li>Maior cota de recursos online</li></ul></article><article class="plan"><p class="plan-label">Referência de lançamento</p><p class="plan-name">Equipe</p><p class="plan-price"><strong>R$ 149,90</strong><span>/mês</span></p><p class="plan-annual">referência anual: R$ 1.499</p><ul><li>Até 10 usuários</li><li>Papéis e permissões</li><li>Centro de conflitos</li><li>Cota compartilhada da equipe</li></ul></article></div><div class="billing-note"><p><strong>Teste de 15 dias no lançamento.</strong> A avaliação será vinculada à assinatura do Google Play e, se não for cancelada antes do fim, será convertida no plano escolhido conforme as condições mostradas pela loja.</p><p>Preço, moeda, impostos, período, renovação e elegibilidade serão confirmados pelo Google Play. Não existe compra neste site, plano gratuito permanente, IA ilimitada ou armazenamento ilimitado. Durante os testes fechados, o acesso permanece restrito aos participantes autorizados.</p></div></div></section>${cta()}`;
writeRoute('/planos', shell({ title: 'Planos do Rumman | ERP para pequenas empresas', description: 'Conheça as referências dos planos Essencial, Pro e Equipe do Rumman e como funcionará o teste de 15 dias pelo Google Play.', canonical: '/planos', current: 'plans', body: plansBody, structured: { ...software, url: `${origin}/planos` } }));

const faqItems = [['Para que tipo de empresa o Rumman foi pensado?', 'O foco inicial são pequenas empresas de serviços com fluxo de orçamento, ordem, material ou estoque, compra, execução e cobrança, como manutenção, instalação, assistência técnica, climatização e pequenas oficinas. Comércio com vários locais, locações e equipes móveis também possuem fluxos específicos.'], ['O Rumman já está disponível no Google Play?', 'O aplicativo está em testes fechados no Google Play, com acesso restrito aos participantes autorizados. A disponibilidade pública virá somente depois da validação desta etapa; não há distribuição indiscriminada de acesso a testadores.'], ['Tudo fica apenas no celular?', 'Não. O banco operacional fica prioritariamente no aparelho e as rotinas locais continuam sem internet quando possível. Com equipe ou sincronização ativa, registros estruturados do workspace também são sincronizados com o backend para aparelhos autorizados. Fotos, arquivos externos, credenciais, tokens e caminhos locais ficam fora desse payload.'], ['O Rumman controla vários depósitos ou locais?', 'Sim. A base atual possui depósitos, lojas, veículos ou locais de evento, saldo por local, transferências atômicas, reservas, separação, inventário físico e saldo consolidado. Transferir entre locais não cria uma entrada ou saída falsa no total.'], ['Como funciona o financeiro?', 'O Rumman reúne receitas, despesas, contas a receber e a pagar, categorias e filtros. Também oferece projeção de caixa em 7, 30 e 90 dias, DRE gerencial simplificada, comparação com período equivalente e exportações PDF e XLSX.'], ['O Rumman atende locações?', 'Sim. O fluxo atual inclui reserva por período, proteção contra dupla agenda, retirada ou entrega, devolução, recebimento e conclusão vinculada ao Financeiro.'], ['A IA decide ou executa sozinha?', 'Não. A fila inicial usa regras locais e determinísticas para priorizar fatos da operação. O Assistente pode apoiar interpretação quando solicitado, mas ações sensíveis permanecem sob confirmação humana.'], ['O Rumman responde por voz?', 'Não há resposta neural por voz disponível. Quando o aparelho suporta, a voz pode ser usada como entrada ou ditado. O envio ao Assistente só acontece quando o usuário confirma.'], ['Como funciona o backup?', 'O Android pode restaurar a base operacional por meio do backup da Conta Google, sujeito aos limites do sistema. O usuário também pode criar um arquivo .rumman criptografado, manual ou diário, e salvá-lo em uma pasta ou provedor escolhido no seletor do Android. A restauração valida o arquivo antes de substituir a base.'], ['O Rumman vende dados ou exibe anúncios?', 'Não. O Rumman não vende dados e não exibe anúncios. Consulte a Política de Privacidade para entender dados locais, sincronização, prestadores e exclusão.']];
const faqBody = `${pageHero('Perguntas frequentes', 'O que saber antes de começar.', 'Respostas objetivas sobre produto, dados, inteligência, estoque e disponibilidade.', illustration('illustration-help.svg'))}<section class="section faq-section"><div class="wrap faq-layout"><div class="section-heading"><p class="eyebrow">Rumman</p><h2>Clareza também faz parte do produto.</h2></div><div class="faq-list">${faqItems.map(item => `<details><summary>${item[0]}</summary><p>${item[1]}</p></details>`).join('')}</div></div></section>${cta()}`;
