  const supportPage = `${pageHero(support.eyebrow, support.title, support.lead, illustration('illustration-help.svg'))}<section class="section support-section"><div class="wrap support-grid"><article><h2>${support.cards[0][0]}</h2><p><a class="text-link" href="mailto:e-mail@rumman.app.br">e-mail@rumman.app.br</a></p><p>${support.cards[0][1]}</p></article><article><h2>${support.cards[1][0]}</h2><p>${support.cards[1][1]}</p><a class="text-link" href="${routeFor(locale, 'deletion')}">${support.cards[1][2]} <span aria-hidden="true">→</span></a></article><article><h2>${support.cards[2][0]}</h2><p>${support.cards[2][1]}</p></article></div></section>`;
