const localizedCoreRoutes = Object.entries(localizedRoutes)
  .filter(([locale]) => locale !== 'pt')
  .flatMap(([, route]) => Object.values(route));
const localizedArticleRoutes = Object.keys(localizedPageCopy).flatMap(locale => articles.map(article => localizedArticlePath(locale, article)));
const routes = [...new Set(['/', '/recursos', '/como-funciona', '/como-usar', '/casos-de-uso', '/planos', '/faq', '/blog/', ...articles.map(a => `/blog/${a.slug}`), '/privacidade', '/termos', '/excluir-conta', '/suporte', ...localizedCoreRoutes, ...localizedArticleRoutes])];
const sitemap = `<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n${routes.map((route, index) => `  <url><loc>${origin}${route}</loc><lastmod>${published}</lastmod><changefreq>${route.endsWith('/blog/') ? 'weekly' : 'monthly'}</changefreq><priority>${index === 0 ? '1.0' : route.includes('/blog/') ? '0.7' : '0.8'}</priority></url>`).join('\n')}\n</urlset>\n`;
writeFileSync(join(root, 'sitemap.xml'), sitemap, 'utf8');

const feed = `<?xml version="1.0" encoding="UTF-8"?><rss version="2.0"><channel><title>Blog Rumman</title><link>${origin}/blog/</link><description>Gestão prática para pequenas empresas.</description><language>pt-BR</language>${articles.map(a => `<item><title>${a.title}</title><link>${origin}/blog/${a.slug}</link><guid>${origin}/blog/${a.slug}</guid><pubDate>Sun, 26 Jul 2026 12:00:00 -0300</pubDate><description>${a.description}</description></item>`).join('')}</channel></rss>`;
writeFileSync(join(root, 'feed.xml'), feed, 'utf8');

const accessFile = join(root, '.htaccess');
let access = readFileSync(accessFile, 'utf8');
access = access.replace(
  /connect-src 'self'[^;]*;/,
  "connect-src 'self' https://cloudflareinsights.com;"
);
access = access.replace(
  /script-src 'self'[^;]*;/,
  `script-src 'self' https://static.cloudflareinsights.com ${[...cspHashes].join(' ')};`
);
writeFileSync(accessFile, access, 'utf8');

process.stdout.write(`Páginas geradas: ${routes.length} rotas e ${articles.length} artigos.\n`);
